+
+    @Test
+    void tourismTaxWithMultipleGuests() {
+        Reservation multiGuest = book(201, "2027-07-01", "2027-07-04", RatePlan.STANDARD);
+        service.confirm(multiGuest.id());
+
+        String csv = new TourismTaxReport(store).generate(YearMonth.of(2027, 7));
+
+        // 3 nights, 1 guest = 4.50 * 1 * 3 = 13.50
+        assertEquals("""
